<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;
use App\Support\LegacyResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Throwable;
class MastersController extends Controller
{
 public function plants(){ try{return response()->json(['success'=>true,'data'=>DB::table('plants')->where('is_active',true)->orderBy('name')->get()->map(fn($x)=>LegacyResponse::normalize($x))->all()]);}catch(Throwable $e){return $this->err($e);} }
 public function createPlant(Request $r){if(!$r->input('name')||!$r->input('code'))return response()->json(['success'=>false,'message'=>'name and code required'],400);try{$id=DB::table('plants')->insertGetId(['name'=>$r->input('name'),'code'=>strtoupper($r->input('code')),'is_active'=>true,'created_at'=>now()]);return response()->json(['success'=>true,'data'=>LegacyResponse::normalize(DB::table('plants')->where('id',$id)->first())],201);}catch(Throwable $e){return $this->err($e);} }
 public function updatePlant(Request $r,$id){try{DB::table('plants')->where('id',$id)->update(['name'=>$r->input('name'),'code'=>strtoupper((string)$r->input('code')),'is_active'=>$r->boolean('is_active')]);$x=DB::table('plants')->where('id',$id)->first();if(!$x)return response()->json(['success'=>false,'message'=>'Plant not found'],404);return response()->json(['success'=>true,'data'=>LegacyResponse::normalize($x)]);}catch(Throwable $e){return $this->err($e);} }
 public function deletePlant($id){try{DB::table('plants')->where('id',$id)->update(['is_active'=>false]);return response()->json(['success'=>true,'message'=>'Plant deactivated']);}catch(Throwable $e){return $this->err($e);} }
 public function departments(Request $r){try{$q=DB::table('departments as d')->join('plants as p','p.id','=','d.plant_id')->select('d.*','p.name as plant_name','p.code as plant_code')->where('d.is_active',true);if($r->filled('plant_id'))$q->where('d.plant_id',$r->input('plant_id'));return response()->json(['success'=>true,'data'=>$q->orderBy('p.name')->orderBy('d.name')->get()->map(fn($x)=>LegacyResponse::normalize($x))->all()]);}catch(Throwable $e){return $this->err($e);} }
 public function createDepartment(Request $r){if(!$r->input('name')||!$r->input('plant_id'))return response()->json(['success'=>false,'message'=>'name and plant_id required'],400);try{$id=DB::table('departments')->insertGetId(['name'=>$r->input('name'),'plant_id'=>$r->input('plant_id'),'is_active'=>true,'created_at'=>now()]);return response()->json(['success'=>true,'data'=>LegacyResponse::normalize(DB::table('departments')->where('id',$id)->first())],201);}catch(Throwable $e){return $this->err($e);} }
 public function updateDepartment(Request $r,$id){try{DB::table('departments')->where('id',$id)->update(['name'=>$r->input('name'),'is_active'=>$r->boolean('is_active')]);$x=DB::table('departments')->where('id',$id)->first();if(!$x)return response()->json(['success'=>false,'message'=>'Department not found'],404);return response()->json(['success'=>true,'data'=>LegacyResponse::normalize($x)]);}catch(Throwable $e){return $this->err($e);} }
 public function deleteDepartment($id){try{DB::table('departments')->where('id',$id)->update(['is_active'=>false]);return response()->json(['success'=>true,'message'=>'Department deactivated']);}catch(Throwable $e){return $this->err($e);} }
 public function shifts(Request $r){try{$q=DB::table('shifts as s')->join('plants as p','p.id','=','s.plant_id')->select('s.*','p.name as plant_name','p.code as plant_code')->where('s.is_active',true);if($r->filled('plant_id'))$q->where('s.plant_id',$r->input('plant_id'));return response()->json(['success'=>true,'data'=>$q->orderBy('p.name')->orderBy('s.code')->get()->map(fn($x)=>LegacyResponse::normalize($x))->all()]);}catch(Throwable $e){return $this->err($e);} }
 public function createShift(Request $r){if(!$r->input('name')||!$r->input('code')||!$r->input('plant_id'))return response()->json(['success'=>false,'message'=>'name, code and plant_id required'],400);try{$id=DB::table('shifts')->insertGetId(['name'=>$r->input('name'),'code'=>strtoupper($r->input('code')),'plant_id'=>$r->input('plant_id'),'is_active'=>true,'created_at'=>now()]);return response()->json(['success'=>true,'data'=>LegacyResponse::normalize(DB::table('shifts')->where('id',$id)->first())],201);}catch(Throwable $e){return $this->err($e);} }
 public function updateShift(Request $r,$id){try{DB::table('shifts')->where('id',$id)->update(['name'=>$r->input('name'),'code'=>strtoupper((string)$r->input('code')),'is_active'=>$r->boolean('is_active')]);$x=DB::table('shifts')->where('id',$id)->first();if(!$x)return response()->json(['success'=>false,'message'=>'Shift not found'],404);return response()->json(['success'=>true,'data'=>LegacyResponse::normalize($x)]);}catch(Throwable $e){return $this->err($e);} }
 public function deleteShift($id){try{DB::table('shifts')->where('id',$id)->update(['is_active'=>false]);return response()->json(['success'=>true,'message'=>'Shift deactivated']);}catch(Throwable $e){return $this->err($e);} }
 private function err(Throwable $e){return response()->json(['success'=>false,'message'=>$e->getMessage()],500);}
}
